fn vstack(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    assert_eq!(
        a.len(),
        b.len(),
        "vstack requires both input arrays to have the same length"
    );
    // Stack them vertically: first row is `a`, second row is `b`.
    vec![a, b]
}

fn make_outer(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    assert_eq!(
        a.len(),
        b.len(),
        "make_outer requires both input arrays to have the same length"
    );
    // `make_outer` does the same thing as `vstack` in this context.
    vec![a, b]
}

fn main() {
    let row1 = vec![1.0, 2.0, 3.0];
    let row2 = vec![4.0, 5.0, 6.0];

    let m1 = vstack(row1.clone(), row2.clone());
    let m2 = make_outer(row1, row2);

    assert_eq!(m1.len(), 2);
    assert_eq!(m1[0], vec![1.0, 2.0, 3.0]);
    assert_eq!(m1[1], vec![4.0, 5.0, 6.0]);

    assert_eq!(m2.len(), 2);
    assert_eq!(m2[0], vec![1.0, 2.0, 3.0]);
    assert_eq!(m2[1], vec![4.0, 5.0, 6.0]);

    println!("All tests passed!");
}